<script setup>
import {inject,ref,computed,watch} from 'vue';
import I from '../components/Icon.vue';
import Modal from '../components/Modal.vue';
import AssetPicker from '../components/AssetPicker.vue';
import MediaPreview from '../components/MediaPreview.vue';
import ResourceStudio from '../components/ResourceStudio.vue';
import MaterialLibrary from '../components/MaterialLibrary.vue';
import AccountLibrary from '../components/AccountLibrary.vue';
import {call,mediaUrl} from '../api';
const props=defineProps({page:String});const {state,busy,act,notify,importAssets,showDialog,refresh}=inject('studio');
const search=ref(''),category=ref('全部素材'),filter=ref('all'),editing=ref(null),picker=ref(false),preview=ref(null),deleting=ref(null),categoryName=ref(''),categoryDialog=ref(false);
const title=computed(()=>({voices:'声音管理',avatars:'形象管理',assets:'素材管理',accounts:'账号管理'}[props.page]||'素材管理'));
const kind=computed(()=>({voices:'voice',avatars:'avatar',accounts:'account'}[props.page]));
const records=computed(()=>state.value[props.page]?.filter(v=>v.name?.includes(search.value))||[]);
const assets=computed(()=>state.value.assets.filter(a=>a.name.includes(search.value)&&(filter.value==='all'||filter.value===a.type)&&(category.value==='全部素材'||a.category===category.value)));
watch(()=>props.page,()=>{search.value='';editing.value=null;preview.value=null;});
function add(){editing.value={name:'',description:'',assetId:'',sampleId:'',remoteId:'',platform:'抖音',category:'全部素材',tags:[]};}
async function save(){const r=await act('保存资源',()=>call('saveResource',{type:kind.value,item:editing.value}));if(r){editing.value=null;notify('资源已保存','success');}}
async function remove(){const target=deleting.value;const r=await act('删除记录',()=>call(props.page==='assets'?'deleteAsset':'deleteResource',props.page==='assets'?{id:target.id}:{type:kind.value,id:target.id}));if(r){deleting.value=null;notify('已删除','success');}}
function selected(a){if(kind.value==='voice')editing.value.sampleId=a.id;else editing.value.assetId=a.id;picker.value=false;}
async function addCategory(){if(!categoryName.value.trim())return;const r=await act('添加分类',()=>call('addCategory',{name:categoryName.value}));if(r){category.value=categoryName.value;categoryName.value='';categoryDialog.value=false;}}
</script>
<template><MaterialLibrary v-if="page==='assets'"/><AccountLibrary v-else-if="page==='accounts'"/><section v-else class="management-page" :class="{'assets-page':page==='assets','accounts-page':page==='accounts','avatars-page':page==='avatars','with-studio':page==='voices'||page==='avatars'}"><div class="management-title"><div><h1>{{title}}</h1><p>{{page==='voices'?'管理配音样本与模型服务音色':page==='avatars'?'管理数字人形象视频':page==='accounts'?'管理发布账号记录与连接状态':'统一管理创作中使用的音频、视频、图片和字幕'}}</p></div><button v-if="page!=='assets'&&page!=='accounts'" class="primary" @click="page==='assets'?importAssets('all'):add()"><I name="Plus"/>{{page==='assets'?'导入素材':page==='voices'?'添加声音':page==='avatars'?'上传形象':'添加账号'}}</button></div><ResourceStudio v-if="page==='voices'||page==='avatars'" :key="page" :page="page"/><div v-if="page==='assets'" class="toolbar asset-main-toolbar"><button @click="categoryDialog=true"><I name="Plus"/>新建分类</button><button class="primary" @click="importAssets('all')"><I name="Upload"/>上传视频或图片</button><div class="spacer"></div><div class="search"><input v-model="search" placeholder="搜索素材..." aria-label="搜索素材"/><I name="Search" :size="20"/></div></div><div v-if="page==='assets'" class="asset-management"><aside class="card category-nav"><header><h3>分类管理</h3><button class="icon-button" aria-label="刷新素材分类" @click="refresh()"><I name="RefreshCw" :size="18"/></button></header><button v-for="c in state.categories" :key="c" :class="{active:category===c}" @click="category=c"><span>{{c}}</span><span class="category-count">{{state.assets.filter(a=>c==='全部素材'||a.category===c).length}}</span></button></aside><article class="card asset-content"><header class="asset-content-heading"><strong>{{category}} <small>({{assets.length}})</small></strong><div class="segmented"><button v-for="[id,name] in [['all','全部'],['video','视频'],['image','图片'],['audio','音频'],['text','文本']]" :key="id" :class="{active:filter===id}" @click="filter=id">{{name}}</button></div><button class="icon-button" aria-label="刷新素材" @click="refresh()"><I name="RefreshCw" :size="18"/></button></header><div v-if="assets.length" class="asset-grid"><article v-for="a in assets" :key="a.id" class="asset-card"><button class="asset-open" @click="preview=a"><img v-if="a.type==='image'" :src="mediaUrl(a.id)" alt=""/><div v-else class="asset-thumbnail"><I :name="a.type==='video'?'Video':a.type==='audio'?'Volume2':'FileText'" :size="40"/></div><strong>{{a.name}}</strong></button><div class="asset-meta"><small>{{(a.size/1024/1024).toFixed(2)}}MB</small><span>{{a.duration?Number(a.duration).toFixed(1)+'秒':''}}</span><button aria-label="删除素材" @click="deleting=a"><I name="Trash2" :size="15"/></button></div><select :value="a.category" aria-label="素材分类" @change="act('修改分类',()=>call('updateAsset',{id:a.id,category:$event.target.value}))"><option v-for="c in state.categories" :key="c">{{c}}</option></select></article></div><div v-else class="empty-state"><I name="FolderOpen" :size="48"/><h3>暂无素材</h3><p>导入本地文件，为创作准备素材。</p><button class="primary" @click="importAssets('all')">导入素材</button></div></article></div><div v-else-if="page==='accounts'" class="toolbar account-main-toolbar"><button class="primary" @click="add"><I name="Plus" :size="16"/>添加账号</button><div class="spacer"></div><div v-if="records.length" class="search"><I name="Search" :size="18"/><input v-model="search" placeholder="输入名称搜索" aria-label="搜索账号"/></div></div><article v-if="page!=='assets'" class="card resource-library"><div v-if="page!=='accounts'" class="toolbar resource-library-heading"><strong>{{page==='voices'?'我的声音':page==='avatars'?'我的形象':'我的账号'}} <span class="badge">{{records.length}}</span></strong><div class="spacer"></div><button @click="add"><I name="Plus" :size="16"/>添加</button><div class="search"><I name="Search" :size="18"/><input v-model="search" placeholder="输入名称搜索" aria-label="搜索资源"/></div></div><div v-if="records.length" class="resource-grid"><article v-for="r in records" :key="r.id" class="resource-card"><div class="resource-visual"><img v-if="page==='avatars'&&r.posterId" :src="mediaUrl(r.posterId)" alt=""/><I v-else :name="page==='voices'?'Volume2':page==='avatars'?'User':'Users'" :size="44"/><span class="badge">{{page==='accounts'?'未连接':page==='voices'?(r.remoteId?'已填写音色ID':'仅保存样本'):'本地形象'}}</span></div><h3>{{r.displayName||r.name}}</h3><p class="hint">{{r.description||r.platform||'尚未填写描述'}}</p><div class="toolbar"><button @click="editing=JSON.parse(JSON.stringify(r))">编辑</button><button v-if="r.assetId||r.sampleId" @click="preview=state.assets.find(a=>a.id===(r.assetId||r.sampleId))"><I name="Play" :size="15"/>预览</button><div class="spacer"></div><button aria-label="删除资源" @click="deleting=r"><I name="Trash2" :size="17"/></button></div></article></div><div v-else class="empty-state"><I :name="page==='voices'?'Volume2':page==='avatars'?'Video':'Users'" :size="52"/><h3>{{page==='voices'?'还没有声音':page==='avatars'?'还没有数字人形象':'还没有发布账号'}}</h3><p>{{page==='voices'?'上传声音样本，或填写已接入服务的音色ID。':page==='avatars'?'上传本人或已获授权的视频，建立形象档案。':'添加账号记录后，还需要接入平台登录和发布服务。'}}</p><button class="primary" @click="add"><I name="Plus"/>立即添加</button></div></article></section>
<Modal v-if="editing" :title="(editing.id?'编辑':'添加')+(page==='voices'?'声音':page==='avatars'?'形象':'账号')" variant="resource" @close="editing=null"><label v-if="page==='accounts'">平台类型<select v-model="editing.platform"><option v-for="p in ['抖音','快手','小红书','视频号','哔哩哔哩']" :key="p">{{p}}</option></select></label><label>{{page==='accounts'?'账号名称':'名称'}} <b class="required">*</b><input v-model="editing.name" :maxlength="page==='accounts'?30:10" :placeholder="page==='accounts'?'输入账号名称或用户名':'请输入名称'"/></label><template v-if="page!=='accounts'"><label>描述<textarea v-model="editing.description" maxlength="200" placeholder="描述风格或用途"></textarea></label><button class="upload-zone full" @click="picker=true"><I name="Upload"/><span>{{state.assets.find(a=>a.id===(editing.assetId||editing.sampleId))?.name||'上传或选择'+(page==='voices'?'声音样本':'形象视频')}}</span></button><template v-if="page==='voices'"><label>模型服务中的音色ID<input v-model="editing.remoteId" placeholder="填写服务实际返回的ID"/></label><p class="hint">上传样本仅保存文件，不会自动完成声音克隆训练。实际克隆服务尚未接入。</p></template></template><template v-else><label>显示名称<input v-model="editing.displayName" maxlength="30" placeholder="输入显示名称（可选）"/></label></template><template #footer><button @click="editing=null">取消</button><button class="primary" :disabled="!!busy" @click="save">{{editing.id?'保存':'添加'}}</button></template></Modal>
<Modal v-if="categoryDialog" title="新建分类" variant="resource" @close="categoryDialog=false"><label>分类名称<input v-model="categoryName" maxlength="30" placeholder="请输入分类名称" @keyup.enter="addCategory"/></label><template #footer><button @click="categoryDialog=false">取消</button><button class="primary" :disabled="!!busy||!categoryName.trim()" @click="addCategory">添加</button></template></Modal>
<AssetPicker v-if="picker" :kind="page==='voices'?'audio':'video'" @close="picker=false" @select="selected"/>
<Modal v-if="preview" :title="preview.name" wide @close="preview=null"><MediaPreview v-if="preview.type!=='text'" :id="preview.id" :type="preview.type"/><p v-else class="hint">文本文件可在学习对标或字幕编辑中导入。</p></Modal>
<Modal v-if="deleting" title="确认删除" @close="deleting=null"><p>删除“{{deleting.name}}”？被任务引用的资源需要先解除引用。</p><template #footer><button @click="deleting=null">取消</button><button class="danger-button" @click="remove">删除</button></template></Modal>
</template>
